package main

import (
	"math"
	"bytes"
	"encoding/json"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strconv"
)

// Lookup is the small lookup file for the browser extension (indices/lookup.json on
// GitHub Pages, generated by the pages workflow and not kept in the repository).
// It only holds what a pixiv page needs: is this post / this account known?
//
// URL templates are included so the extension does not hard-code them:
// {id} and {slug} are used as-is, {name} must be URL-encoded by the consumer.
type Lookup struct {
	Version int               `json:"version"`
	URLs    map[string]string `json:"urls"`
	// Posts: pixiv post ids that exist on koikatsucards (sorted).
	Posts []int64 `json:"posts"`
	// Authors: koikatsucards author slug -> display name (only slugs used by Users).
	Authors map[string]string `json:"authors"`
	// Users: pixiv user id -> koikatsucards author slugs and bepis author names.
	Users map[string]*LookupUser `json:"users"`
	// Telegram: where pixiv posts and accounts were seen in the Telegram chats of
	// config/telegram_chats.json (omitted when there are none).
	Telegram *LookupTelegram `json:"telegram,omitempty"`
}

// LookupTelegram maps a pixiv id to a Telegram message (among the chats that are not
// no_lookup, so a private sighting never hides a public one; for posts the first chat of the
// chat list that has it, for users the earliest message) that links it, as the path of
// its t.me link: "name/123" (public chat), "c/1234567890/123" (private chat or channel), with
// the forum topic after the chat when the message is in one ("name/42/123"). The link is
// https://t.me/<path>. Chats marked no_lookup in the chat list are not included.
type LookupTelegram struct {
	Posts map[string]string `json:"posts"` // pixiv post id
	Users map[string]string `json:"users"` // pixiv user id
}

// LookupUser is one pixiv account.
type LookupUser struct {
	Authors []string `json:"authors"`         // koikatsucards author slugs
	Bepis   []string `json:"bepis,omitempty"` // bepis author names (cardAuthor values)
	// Pawchive is the creator with the most favorites among the account's matches.
	Pawchive *LookupPawchive `json:"pawchive,omitempty"`
}

// LookupPawchive identifies a pawchive creator; URL template "pawchive" in Lookup.URLs.
type LookupPawchive struct {
	Service string `json:"service"`
	ID      string `json:"id"`
}

const lookupVersion = 1

// writeLookup builds the lookup file from m and writes it to path. It is
// not kept in the repository: the GitHub Pages workflow generates and deploys it.
func writeLookup(m *Mapping, tg *tgExport, path string) error {
	ext := m.buildLookup(tg)
	if err := saveJSONCompact(path, ext); err != nil {
		return err
	}
	log.Printf("lookup file: %d posts, %d accounts -> %s", len(ext.Posts), len(ext.Users), path)
	if ext.Telegram != nil {
		log.Printf("lookup file: %d telegram posts, %d telegram accounts", len(ext.Telegram.Posts), len(ext.Telegram.Users))
	}
	return nil
}

// buildLookup builds the lookup structure; tg (may be nil) adds the Telegram sightings.
func (m *Mapping) buildLookup(tg *tgExport) *Lookup {
	s := &Lookup{
		Version: lookupVersion,
		URLs: map[string]string{
			"post":     koikatsuBase + "/contents/pixiv-{id}",
			"author":   koikatsuBase + "/search?author={slug}",
			"bepis":    bepisBase + "?cardAuthor={name}",
			"pawchive": pawchiveBase + "/{service}/user/{id}",
		},
		Posts:   make([]int64, 0, len(m.Posts)),
		Authors: map[string]string{},
		Users:   map[string]*LookupUser{},
	}

	for id := range m.Posts {
		if n, err := strconv.ParseInt(id, 10, 64); err == nil {
			s.Posts = append(s.Posts, n)
		}
	}
	sort.Slice(s.Posts, func(i, j int) bool { return s.Posts[i] < s.Posts[j] })

	for id, pu := range m.PixivUsers {
		u := &LookupUser{Authors: []string{}}
		best := pu.Pawchive // the account's own match wins
		for _, slug := range pu.AuthorSlugs {
			au := m.Authors[slug]
			if au == nil {
				continue
			}
			u.Authors = addUnique(u.Authors, slug)
			s.Authors[slug] = au.Name
			for _, b := range au.Bepis {
				u.Bepis = addUnique(u.Bepis, b.Name)
			}
			// otherwise fall back to the strongest match among its authors
			if pu.Pawchive == nil && au.Pawchive != nil && (best == nil || au.Pawchive.Favorited > best.Favorited) {
				best = au.Pawchive
			}
		}
		if best != nil {
			u.Pawchive = &LookupPawchive{Service: best.Service, ID: best.ID}
		}
		// accounts with neither an author tag nor a pawchive match are covered by Posts only
		if len(u.Authors) > 0 || u.Pawchive != nil {
			s.Users[id] = u
		}
	}
	s.Telegram = tg.lookup()
	return s
}

// tgMessagePath is the t.me link path of a message (see LookupTelegram). Topic 1 is the General
// topic, which is also what chats without topics report, and has no place in the link.
func tgMessagePath(chat string, topic, msg int) string {
	if topic > 1 {
		return chat + "/" + strconv.Itoa(topic) + "/" + strconv.Itoa(msg)
	}
	return chat + "/" + strconv.Itoa(msg)
}

// lookup returns the Telegram part of the lookup file, nil when there is nothing to show.
func (e *tgExport) lookup() *LookupTelegram {
	if e == nil {
		return nil
	}
	out := &LookupTelegram{Posts: map[string]string{}, Users: map[string]string{}}
	// Among the sightings in chats that are not no_lookup: for posts the chat that comes first in
	// the chat list (a chat without a known position comes last), for users the earliest message.
	// Ties go to the earlier message, then the chat key.
	pick := func(l *tgPixivLink, byOrder bool) (string, bool) {
		rank := func(s *tgSighting) int {
			if st := e.Chats[s.Chat]; byOrder && st != nil && st.Order > 0 {
				return st.Order
			}
			return math.MaxInt
		}
		var best *tgSighting
		for i := range l.Sightings {
			s := &l.Sightings[i]
			if st := e.Chats[s.Chat]; st != nil && st.NoLookup {
				continue
			}
			if best == nil || rank(s) < rank(best) || rank(s) == rank(best) && earlierSighting(*s, *best) {
				best = s
			}
		}
		if best == nil {
			return "", false
		}
		return tgMessagePath(best.Chat, best.Topic, best.MessageID), true
	}
	for id, p := range e.PixivPosts {
		if path, ok := pick(p, true); ok {
			out.Posts[id] = path
		}
	}
	for id, u := range e.PixivUsers {
		if path, ok := pick(u, false); ok {
			out.Users[id] = path
		}
	}
	if len(out.Posts) == 0 && len(out.Users) == 0 {
		return nil
	}
	return out
}

// saveJSONCompact writes minified JSON atomically (the lookup file is shipped to clients).
func saveJSONCompact(path string, v any) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, b, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

// saveJSONIndent writes v indented with two spaces, without escaping <, > and & so
// names such as "<!>" stay readable in the file.
func saveJSONIndent(path string, v any) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(v); err != nil {
		return err
	}
	b := bytes.TrimRight(buf.Bytes(), "\n")
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, b, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}
